var EXTRA=[{dot:"gray",j:"Knee Surgery & Related Research",h:"Protesi a raggio singolo: nessuna differenza fra le due varianti",v:"Confronto a lungo termine fra le versioni che conservano o sacrificano il legamento crociato posteriore in una popolazione asiatica: sopravvivenza elevata per entrambe, senza differenza clinica.",pmid:'42698118',doi:'10.1186/s43019-026-00349-x',temi:["protesi totale","raggio singolo","sopravvivenza"]},{dot:"gray",j:"Journal of Robotic Surgery",h:"Il sistema robotico ROSA conferma buoni risultati a medio termine",v:"Prima coorte pubblicata sui risultati a distanza con questa piattaforma robotica: nessun confronto diretto con la chirurgia convenzionale nello stesso studio.",pmid:'42671717',doi:'10.1007/s11701-026-03907-3',temi:["protesi robotica","ROSA","medio termine"]},{dot:"gray",j:"The Journal of Arthroplasty",h:"Un angolo tibiale più stretto non compromette la protesi ad allineamento cinematico",v:"Uno scostamento anatomico che un tempo faceva preferire l'allineamento meccanico non peggiora l'esito a due anni con l'allineamento cinematico non ristretto.",pmid:'42697451',doi:'10.1016/j.arth.2026.08.055',temi:["protesi totale","allineamento cinematico","angolo tibiale"]},{dot:"gray",j:"The Journal of Arthroplasty",h:"Non tutti i quadricipiti sono uguali nell'artrosi di ginocchio",v:"Analisi per sottogruppi del volume del muscolo quadricipite in pazienti candidati a protesi: profili diversi potrebbero avere implicazioni riabilitative differenti, ancora da validare clinicamente.",pmid:'42697447',doi:'10.1016/j.arth.2026.08.051',temi:["protesi totale","quadricipite","fenotipi"]},{dot:"gray",j:"The Knee",h:"Fissazione a cappio fisso o regolabile: stessa efficacia nel LCA",v:"Meta-analisi di studi comparativi sulla fissazione femorale dell'innesto: nessuna differenza clinicamente rilevante fra le due tecniche di sospensione.",pmid:'42566984',doi:'10.1016/j.knee.2026.104607',temi:["lca","fissazione femorale","meta-analisi"]},{dot:"gray",j:"Arthroscopy Techniques",h:"Una nuova tecnica «ripstop» per la radice meniscale mediale",v:"Nota tecnica su un rinforzo di sutura obliquo per la riparazione della radice meniscale mediale, alternativo alla tecnica transtibiale pull-out; nessun dato clinico riportato.",pmid:'42597597',doi:'10.1016/j.eats.2026.104013',temi:["menisco","radice meniscale","tecnica chirurgica"]},{dot:"gray",j:"Arthroscopy Techniques",h:"Sutura a ponte per la frattura da avulsione del crociato anteriore",v:"Nota di tecnica per la fissazione artroscopica della frattura da avulsione tibiale del LCA attraverso tunnel transtibiali; nessun dato clinico riportato.",pmid:'42639273',doi:'10.1016/j.eats.2026.104112',temi:["lca","frattura avulsione","tecnica chirurgica"]},{dot:"gray",j:"Orthopaedic Journal of Sports Medicine",h:"Dopo l'MPFL, il quadricipite si attiva meno al rientro allo sport",v:"Studio elettromiografico su adolescenti operati di MPFL: asimmetrie di attivazione del vasto mediale persistono fino al momento del rientro in campo.",pmid:'42568778',doi:'10.1177/23259671261466476',temi:["mpfl","elettromiografia","rientro allo sport"]},{dot:"gray",j:"Journal of Clinical Medicine",h:"Un nuovo indice di asimmetria trocleare per l'instabilità rotulea",v:"Studio caso-controllo di imaging: un rapporto derivato dalla forma della troclea distingue l'instabilità dalla sola rotula alta, soglia ancora da validare esternamente.",pmid:'42590043',doi:'10.3390/jcm15155940',temi:["instabilità rotulea","imaging","troclea"]},{dot:"gray",j:"Sports Medicine - Open",h:"Dopo la rottura del LCA il cervello «spegne» il quadricipite",v:"Studio di risonanza funzionale: l'inibizione muscolare artrogenica dopo lesione acuta del LCA ha una firma cerebrale misurabile a livello cerebellare e sottocorticale.",pmid:'42642554',doi:'10.1186/s40798-026-00947-3',temi:["inibizione muscolare","fmri","neuroscienze"]},{dot:"gray",j:"JAAOS Global Research & Reviews",h:"Gli «scriba» con intelligenza artificiale arrivano in sala operatoria ortopedica",v:"Revisione narrativa sugli strumenti di documentazione automatica in ortopedia: promettenti per ridurre il carico burocratico, ancora da validare per specialità.",pmid:'42627719',doi:'10.5435/JAAOSGlobal-D-25-00398',temi:["intelligenza artificiale","documentazione clinica","organizzazione"]},{dot:"gray",j:"Journal of ISAKOS",h:"Aggiungere il legamento patello-tibiale riduce ulteriormente la traslazione rotulea",v:"Studio cadaverico: la ricostruzione combinata con il legamento patello-tibiale mediale controlla meglio la traslazione laterale della sola MPFL, senza aumentare la pressione media di contatto.",pmid:'42567452',doi:'10.1016/j.jisako.2026.101200',temi:["mpfl","instabilità rotulea","biomeccanica"]}];
var SCOPERTE=[{t:"Il cervello che sente diversamente: la magnetoencefalografia distingue il dolore neuropatico nell'artrosi",v:"Fuori dai soliti radar: 192 pazienti con artrosi di ginocchio, registrazione magnetoencefalografica del dolore evocato e modelli di apprendimento automatico interpretabili distinguono con discreta accuratezza (AUC 0,77) chi ha una componente di dolore neuropatico da chi no. Non cambia la pratica chirurgica di domani, ma è un esempio concreto di come la neuroingegneria comincia a misurare ciò che finora si chiedeva solo a parole.",pmid:'42621580',doi:'10.2147/JPR.S622996',temi:["neuroscienze","intelligenza artificiale","dolore"]},{t:"Dalla Cina, una rassegna su come l'intelligenza artificiale multimodale anticipa la diagnosi di artrosi",v:"Una revisione cinese sintetizza come unire radiografia, risonanza, dati clinici e cammino in un solo modello di apprendimento profondo per riconoscere l'artrosi di ginocchio nelle sue fasi più precoci, quando i segni radiografici sono ancora minimi. Gli stessi autori avvertono che la validazione multicentrica indipendente resta il collo di bottiglia prima di qualunque uso clinico.",pmid:'42656119',doi:'10.7507/1001-5515.202601026',temi:["bioingegneria","intelligenza artificiale","imaging"]},{t:"I farmaci per diabete e obesità entrano nella medicina del dolore da artrosi",v:"Una rassegna narrativa di medicina del dolore esamina il ruolo emergente degli agonisti del GLP-1 (semaglutide, tirzepatide) nel dolore lombare e di ginocchio legato all'obesità: non sostituiscono la valutazione ortopedica né la riabilitazione, ma la perdita di peso clinicamente rilevante che producono potrebbe diventare un alleato terapeutico indiretto sempre più comune nei pazienti che arrivano in ambulatorio.",pmid:'42572056',doi:'10.1007/s11916-026-01546-9',temi:["farmacologia","obesità","campi adiacenti"]}];
var SOC={"1": {"video": "Un gruppo di ricercatori ha esaminato sei sistemi robotici usati oggi in sala operatoria per l'ortopedia, incluso quello impiegato nel nostro studio per le protesi di ginocchio. La conclusione è chiara: questi robot rendono l'intervento più preciso, ma non sono davvero intelligenti nel senso di poter decidere da soli — restano strumenti che il chirurgo guida interamente, dall'inizio alla fine. Un punto utile da sapere quando si sente parlare di chirurgia robotica come se fosse automatica: non lo è, ed è bene che resti così."}, "2": {"video": "Uno studio spagnolo ha seguito per cinque anni oltre cento calciatori professionisti operati al legamento crociato del ginocchio. Quasi tutti sono tornati a giocare, in media dopo nove mesi. Ma con gli anni molti hanno giocato meno partite, a un livello più basso, e il loro valore di mercato è sceso in modo significativo — un segnale che tornare in campo non equivale a tornare al livello di prima, un'informazione utile per calibrare le aspettative dei pazienti sportivi."}, "3": {"video": "Uno studio cinese ha osservato pazienti con instabilità ricorrente della rotula, alcuni dei quali presentavano un particolare comportamento della rotula durante il movimento del ginocchio. Chi aveva questo segno prima dell'intervento ha ottenuto risultati meno buoni dopo la sola ricostruzione del legamento mediale, con un rischio più alto di nuova instabilità — un elemento utile per decidere se aggiungere altri gesti chirurgici nello stesso intervento."}, "4": {"video": "Una revisione di otto studi ha confrontato la pianificazione della protesi di ginocchio fatta con l'aiuto dell'intelligenza artificiale con quella tradizionale. Il risultato: nessun vantaggio chiaramente dimostrato nella scelta della taglia dell'impianto, se non quando l'intelligenza artificiale lavora insieme a immagini tridimensionali della tomografia computerizzata — un campo ancora da approfondire prima di poterlo raccomandare."}, "5": {"video": "Uno studio americano ha seguito per oltre vent'anni pazienti sottoposti a trapianto di menisco da donatore, una procedura diversa dalla più comune riparazione del menisco. I risultati mostrano una buona durata dell'innesto nel tempo, con un calo progressivo, e un segnale — da confermare — che le pazienti donne potrebbero avere un rischio leggermente più alto di fallimento. Non è una tecnica eseguita in questo studio ma un'informazione utile per chi la valuta altrove."}};
var SOCV={"1": {"video": {"chir": ["Una revisione narrativa appena pubblicata analizza sei piattaforme robotiche commerciali per la chirurgia ortopedica — MAKO, ROSA, CORI/NAVIO, VELYS, ExcelsiusGPS e TSolution One — chiedendosi se meritino davvero l'etichetta di intelligenza artificiale. La risposta degli autori è netta: nessuna soddisfa oggi i criteri tecnici di un sistema realmente autonomo, capace di percepire l'ambiente chirurgico, ragionare e adattarsi senza supervisione continua.", "Tutte, VELYS compreso, restano quella che gli autori chiamano assistenza di precisione: migliorano l'accuratezza del taglio osseo, il posizionamento della componente e la ripetibilità del gesto, dati già documentati in letteratura clinica. Percezione continua, ragionamento adattivo e apprendimento in sala restano invece capacità dichiarate come obiettivo futuro, non funzioni disponibili nei sistemi oggi in commercio. La differenza tecnica fra assistere e decidere è più sottile di quanto il marketing lasci intendere.", "Il lavoro è una revisione narrativa, non sistematica, senza dati clinici originali: la selezione delle fonti non è riproducibile e il confronto fra piattaforme resta qualitativo. Gli stessi autori indicano che il passo successivo — visione artificiale, modelli fondazionali, gemelli digitali paziente-specifici — richiederà anni di validazione multicentrica e un quadro regolatorio ancora da scrivere, mantenendo sempre il chirurgo al comando della decisione clinica."], "misto": ["Una nuova analisi scientifica ha guardato ai sei principali robot usati oggi in chirurgia ortopedica nel mondo — tra cui il sistema VELYS, impiegato anche nella nostra pratica per le protesi di ginocchio — per capire se meritino davvero di essere chiamati intelligenza artificiale. La risposta è che nessuno, oggi, lo è nel senso tecnico del termine.", "Tutti questi sistemi, spiegano gli autori, aiutano il chirurgo a posizionare l'impianto con grande precisione e rendono l'intervento più ripetibile — un vantaggio reale e già dimostrato. Ma non percepiscono l'ambiente, non ragionano sul caso e non imparano da soli durante l'intervento: eseguono un piano deciso in anticipo dal chirurgo, che resta sempre lui a decidere ogni passaggio.", "È un'analisi di sintesi, non uno studio su pazienti operati, e il confronto fra i diversi sistemi resta descrittivo. Serve soprattutto a mettere ordine fra ciò che i produttori comunicano e ciò che questi robot sanno davvero fare oggi — una distinzione utile per medici di base, fisioterapisti e pazienti quando sentono parlare di chirurgia robotica come se fosse ormai automatica."], "pazienti": ["Una pubblicazione scientifica ha esaminato i robot chirurgici usati oggi in ortopedia, compreso quello impiegato nel nostro studio per le protesi di ginocchio, chiedendosi: sono davvero intelligenti? La risposta, onesta, è no — non ancora, non nel senso in cui lo intendiamo per un'intelligenza artificiale vera e propria.", "Questi strumenti aiutano il chirurgo a posizionare la protesi con una precisione molto alta, ed è un vantaggio concreto per il paziente. Ma non decidono da soli: seguono un piano preparato in anticipo, e ogni scelta durante l'intervento resta sua, dall'inizio alla fine. Il robot esegue, non decide.", "Non è uno studio su pazienti operati, ma una fotografia onesta di che cosa sanno fare oggi questi sistemi. Il messaggio è rassicurante: la tecnologia aiuta, ma la responsabilità e il giudizio clinico restano interamente nelle mani del chirurgo che vi opera."]}, "linkedin": {"chir": ["Sei piattaforme robotiche, un solo verdetto: nessuna è davvero intelligenza artificiale autonoma. Una revisione narrativa su Journal of Robotic Surgery analizza MAKO, ROSA, CORI/NAVIO, VELYS, ExcelsiusGPS e TSolution One rispetto ai criteri tecnici dell'Embodied AI — percezione, ragionamento e adattamento in ciclo continuo.", "\n\nTutti i sistemi, VELYS compreso, restano tecnologie di assistenza di precisione: migliorano accuratezza di taglio, posizionamento della componente e ripetibilità del gesto — vantaggi già documentati in letteratura clinica. Percezione continua dell'ambiente operatorio, ragionamento adattivo in tempo reale e apprendimento continuo restano invece capacità dichiarate come obiettivo futuro, non funzioni disponibili nei sistemi oggi in commercio.", "\n\nRevisione narrativa, non sistematica: nessun dato clinico originale, selezione delle fonti non riproducibile. Gli autori indicano la strada — visione artificiale, modelli fondazionali, apprendimento per rinforzo, gemelli digitali paziente-specifici — condizionata a validazione multicentrica, standard regolatori chiari e un'architettura esplicitamente human-in-command. Per chi lavora ogni giorno con la chirurgia robotica, un promemoria utile: la precisione dello strumento non equivale, oggi, a intelligenza clinica."], "misto": ["Sei dei principali sistemi robotici usati oggi in ortopedia — VELYS compreso — sono davvero intelligenza artificiale? Una revisione appena pubblicata dice di no, non ancora: restano strumenti di assistenza molto precisi, non sistemi autonomi.", "\n\nIl vantaggio è reale: più precisione nel posizionamento dell'impianto, più ripetibilità del gesto chirurgico. Il limite, altrettanto reale: nessuno di questi sistemi percepisce l'ambiente operatorio o si adatta da solo durante l'intervento. Eseguono un piano, non lo inventano.", "\n\nUna lettura utile per chi lavora con pazienti candidati a chirurgia robotica — medici di base, fisioterapisti, pazienti stessi: la tecnologia aiuta il chirurgo, non lo sostituisce, e la differenza conta quando si valuta un intervento."], "pazienti": ["Il robot che opera il ginocchio da solo non esiste — non ancora. Lo dice una ricerca appena pubblicata su sei dei sistemi più usati al mondo, incluso quello della nostra pratica.", "\n\nQuesti robot aiutano il chirurgo a posizionare la protesi con grande precisione. Ma ogni decisione, durante l'intervento, resta sua: il robot esegue un piano, non lo decide da solo.", "\n\nUn chiarimento onesto per chi si informa prima di un intervento: chirurgia robotica non significa chirurgia automatica. Il chirurgo resta al comando, dall'inizio alla fine."]}, "instagram": {"chir": ["Sei robot, una domanda: sono davvero intelligenti?\n\nUna revisione su Journal of Robotic Surgery analizza MAKO, ROSA, CORI/NAVIO, VELYS, ExcelsiusGPS e TSolution One — le piattaforme più usate in chirurgia ortopedica oggi.", "\n\nLa risposta: nessuna soddisfa i criteri tecnici di una vera intelligenza artificiale autonoma. Tutte migliorano precisione e ripetibilità del gesto — dati reali — ma nessuna percepisce, ragiona o si adatta da sola durante l'intervento.", "\n\nÈ una revisione narrativa, non uno studio clinico: un promemoria per non confondere il marketing della «chirurgia robotica intelligente» con ciò che questi sistemi sanno fare davvero oggi. Il chirurgo resta al comando."], "misto": ["Il robot che opera è davvero «intelligente»?\n\nUna nuova analisi ha guardato ai sistemi robotici usati oggi in ortopedia, VELYS compreso. La risposta: non ancora, non del tutto.", "\n\nQuesti sistemi rendono l'intervento più preciso e ripetibile — un vantaggio vero. Ma non percepiscono l'ambiente né ragionano da soli: eseguono un piano deciso in anticipo dal chirurgo.", "\n\nUtile saperlo per capire la differenza fra marketing e realtà tecnica: chi opera resta sempre il chirurgo, non la macchina."], "pazienti": ["Il robot che opera al posto del chirurgo? Non esiste, almeno non ancora.\n\nUna ricerca ha analizzato i robot chirurgici usati oggi in ortopedia, compreso quello della nostra pratica.", "\n\nAiutano a posizionare la protesi con grande precisione — un vantaggio reale per il paziente. Ma ogni decisione resta del chirurgo, dall'inizio alla fine.", "\n\nIl robot esegue, non decide. La responsabilità clinica è, ed resta, interamente umana."]}, "reel": {"chir": ["[IA nei robot ortopedici: bufala o realtà?] Una revisione appena uscita passa in rassegna sei piattaforme robotiche ortopediche — VELYS incluso — e la risposta è netta: nessuna è davvero intelligenza artificiale autonoma.", "[Che cosa sanno fare davvero] Tutte migliorano precisione e ripetibilità del gesto chirurgico — dati reali, documentati. Ma percepire, ragionare, adattarsi da sole? Ancora no: restano strumenti di assistenza, non sistemi decisionali.", "[Il punto per la pratica clinica] Revisione narrativa, non dati originali: utile per separare il marketing dalla tecnica reale. Il chirurgo resta al comando — ed è bene che sia così."], "misto": ["[Il robot in sala operatoria è davvero intelligente?] Una nuova analisi ha guardato ai sistemi robotici usati oggi in ortopedia, VELYS compreso. La risposta: non ancora, non del tutto.", "[Cosa fanno bene] Rendono l'intervento più preciso e ripetibile — un vantaggio vero. Ma non percepiscono, non ragionano da soli: eseguono un piano deciso in anticipo dal chirurgo.", "[Perché conta saperlo] Utile per capire la differenza fra marketing e realtà tecnica: chi opera resta sempre il chirurgo, non la macchina."], "pazienti": ["[Il robot che opera al posto del chirurgo? Non esiste ancora] Una ricerca ha analizzato i robot chirurgici usati oggi in ortopedia. Sono davvero intelligenti? No, non ancora.", "[Cosa fanno per te] Aiutano a posizionare la protesi con grande precisione — un vantaggio reale per il paziente. Ma ogni decisione resta del chirurgo, dall'inizio alla fine.", "[Il messaggio rassicurante] Il robot esegue, non decide. La responsabilità clinica è, ed resta, tutta umana."]}}, "2": {"video": {"chir": ["Una coorte retrospettiva su 132 lesioni del legamento crociato anteriore in 115 calciatori professionisti spagnoli, seguiti fino a cinque anni, mette in discussione un'assunzione comune: che il rientro in campo equivalga al recupero della carriera. Il tasso di rientro è altissimo, 97,7%, in media dopo 9,1 mesi. Ma è quello che succede dopo a raccontare la parte che conta di più.", "Il 35,2% dei giocatori scende di almeno un livello di campionato già nella prima stagione post-infortunio, quota che sale al 61,3% alla quinta stagione. I minuti giocati calano del 46% nel primo anno (p<0,001) e restano circa 21 minuti a partita sotto i valori pre-infortunio per due stagioni intere. Il valore di mercato scende fino al 47,7% a cinque anni, più marcato negli atleti over 30.", "Manca un gruppo di controllo di calciatori non infortunati, quindi non si può isolare l'effetto specifico della lesione dal normale declino di carriera legato all'età; né viene riportato il tipo di innesto o la tecnica chirurgica. Resta comunque un dato utile per il colloquio pre e post-operatorio con l'atleta agonista: il rientro in campo è solo il primo, non l'ultimo, degli esiti da misurare."], "misto": ["Uno studio spagnolo ha seguito per cinque anni 115 calciatori professionisti operati al legamento crociato anteriore del ginocchio. La buona notizia: il 97,7% è tornato a giocare, in media dopo circa nove mesi. La notizia meno raccontata: molti di loro, con gli anni, giocano meno e a un livello più basso.", "Un giocatore su tre scende di categoria già nella prima stagione dopo l'infortunio, e sono sei su dieci alla quinta stagione. I minuti in campo calano quasi della metà nel primo anno e restano più bassi per due stagioni intere. Il valore di mercato del giocatore, misura indiretta ma concreta della sua carriera, scende in modo significativo, soprattutto dopo i trent'anni.", "Mancano un confronto con calciatori non infortunati e i dettagli sulla tecnica chirurgica usata. Il messaggio pratico, comunque, vale anche fuori dal calcio professionistico: «sono tornato a fare sport» e «sono tornato al livello di prima» sono due domande diverse, e la seconda merita più attenzione di quanta ne riceva di solito."], "pazienti": ["Uno studio su calciatori professionisti spagnoli operati al legamento crociato anteriore del ginocchio ha una buona notizia e una più sfumata. La buona notizia: quasi tutti — 97,7% — sono tornati a giocare, in media dopo nove mesi dall'intervento.", "La notizia più sfumata: seguendoli per cinque anni, molti giocatori hanno giocato un po' meno partite e a un livello leggermente inferiore rispetto a prima dell'infortunio, e il loro valore professionale è sceso in modo significativo, specialmente per gli atleti più esperti.", "Riguarda calciatori di altissimo livello, ma il messaggio vale per ogni sportivo: tornare a fare attività fisica dopo un intervento al crociato è un traguardo raggiungibile per la grande maggioranza, ma il pieno recupero delle prestazioni richiede tempo e va valutato con pazienza insieme al proprio chirurgo."]}, "linkedin": {"chir": ["Rientro in campo 97,7%. Eppure un calciatore su tre gioca in una categoria inferiore già dopo un anno. Una coorte retrospettiva su 132 lesioni del LCA in 115 calciatori professionisti spagnoli (Transfermarkt/BeSoccer, verificati su referti medici) segue carriera e valore di mercato fino a 5 anni.", "\n\nMinuti giocati: -46% nella prima stagione post-infortunio (p<0,001), ancora -21 minuti a partita per due stagioni. Livello di campionato: il 35,2% scende di categoria al primo anno, il 61,3% alla quinta. Valore di mercato: calo fino al 47,7% a 5 anni, più marcato negli atleti ≥30 anni.", "\n\nNessun gruppo di controllo di non infortunati, nessun dato su innesto o tecnica chirurgica: il declino può riflettere in parte l'età e il normale turnover di carriera. Ma il messaggio resta solido — il return to play è un indicatore parziale, e nel colloquio prognostico con l'atleta agonista merita di essere accompagnato da altri indicatori di carriera."], "misto": ["Il 97,7% dei calciatori professionisti torna a giocare dopo l'intervento al legamento crociato anteriore. Ma tornare in campo non è tutta la storia: una ricerca spagnola su 115 calciatori lo dimostra con dati di carriera concreti, seguiti fino a cinque anni.", "\n\nUn giocatore su tre scende di categoria già nel primo anno dopo l'infortunio. I minuti giocati calano quasi della metà nella prima stagione. Il valore di mercato, indicatore concreto della carriera, si riduce in modo marcato, soprattutto dopo i trent'anni.", "\n\nMancano un gruppo di paragone e i dettagli tecnici sull'intervento, ma il punto resta valido per chi segue pazienti sportivi: la domanda giusta non è solo «tornerò a giocare», ma «a che livello, e per quanto tempo»."], "pazienti": ["Quasi tutti i calciatori professionisti tornano a giocare dopo l'intervento al legamento crociato del ginocchio — il 97,7%, secondo uno studio spagnolo su 115 atleti. Ma cosa succede dopo, negli anni successivi?", "\n\nSeguendoli per cinque anni, molti giocano un po' meno partite e a un livello leggermente più basso di prima. Il loro valore professionale scende in modo significativo, soprattutto per i giocatori più esperti.", "\n\nUn dato utile per ogni sportivo: tornare all'attività è un traguardo alla portata della maggioranza, ma il recupero pieno delle prestazioni richiede tempo, pazienza e un percorso condiviso con il proprio chirurgo."]}, "instagram": {"chir": ["Return to play 97,7%. Ma la carriera dopo il LCA racconta un'altra storia.\n\nCoorte retrospettiva, 132 lesioni in 115 calciatori professionisti spagnoli, follow-up a 5 anni.", "\n\n1 su 3 scende di categoria già al primo anno (6 su 10 al quinto). Minuti giocati -46% nel primo anno (p<0,001). Valore di mercato: fino a -47,7% a 5 anni.", "\n\nManca un gruppo di controllo e i dati sulla tecnica chirurgica. Ma il punto resta: il return to play è solo l'inizio della valutazione, non la fine."], "misto": ["Tornare a giocare dopo il crociato? Il 97,7% dei calciatori professionisti ci riesce.\n\nMa cosa succede dopo, negli anni successivi? Uno studio spagnolo lo racconta con i numeri.", "\n\nUn giocatore su tre scende di categoria già nel primo anno. I minuti in campo calano quasi della metà. Il valore di mercato scende in modo marcato, soprattutto dopo i 30 anni.", "\n\nLa domanda giusta non è solo «tornerò a giocare», ma «a che livello». Vale per i professionisti — e, con numeri diversi, per ogni sportivo."], "pazienti": ["Dopo l'intervento al crociato, quasi tutti i calciatori tornano in campo.\n\nMa il percorso dopo il rientro racconta di più: uno studio su 115 calciatori professionisti spagnoli lo segue per cinque anni.", "\n\nMolti giocano un po' meno e a un livello leggermente più basso di prima. È un percorso graduale, non un interruttore acceso o spento.", "\n\nIl messaggio per ogni sportivo: tornare all'attività è un traguardo raggiungibile, ma il pieno recupero richiede tempo — da vivere con pazienza insieme al proprio chirurgo."]}, "reel": {"chir": ["[Return to play 97,7%. E poi?] Coorte spagnola, 115 calciatori professionisti, follow-up 5 anni dopo ricostruzione del LCA.", "[I numeri che contano dopo] 1 su 3 scende di categoria al primo anno. Minuti giocati -46% (p<0,001). Valore di mercato fino a -47,7% a 5 anni.", "[Perché conta in ambulatorio] Il rientro in campo è solo il primo indicatore. La carriera reale si misura dopo, negli anni successivi."], "misto": ["[Tornare a giocare non è tutta la storia] Il 97,7% dei calciatori professionisti torna in campo dopo il crociato.", "[Ma poi cosa succede] Un giocatore su tre scende di categoria entro un anno. I minuti calano, il valore di mercato pure.", "[La domanda giusta] Non solo «tornerò a giocare», ma «a che livello» — vale anche per lo sportivo non professionista."], "pazienti": ["[Dopo il crociato, quasi tutti tornano in campo] 97,7% di rientro fra i calciatori professionisti spagnoli operati.", "[Ma il percorso continua] Molti giocano un po' meno e a un livello leggermente più basso di prima, per un po' di tempo.", "[Il messaggio] Recuperare richiede pazienza — un percorso da vivere insieme al proprio chirurgo, passo dopo passo."]}}, "3": {"video": {"chir": ["Una coorte retrospettiva di 85 pazienti con instabilità rotulea ricorrente, operati di ricostruzione dell'MPFL a Pechino, isola un segno clinico preoperatorio con valore prognostico: il jumping patella, la rotula che salta lateralmente durante il movimento invece di scorrere in modo continuo. Torsione tibiale e sperone sovratrocleare ne sono predittori indipendenti, con odds ratio rispettivamente di 7,16 e 30,5.", "Al follow-up finale, chi presentava il jumping preoperatorio ha punteggi Lysholm e Kujala significativamente più bassi della controparte gliding, e tassi più alti di lassità mediale della rotula, malracking residuo, persistenza del jumping stesso, lassità dell'innesto e ri-lussazione — tutte differenze con p<0,05 o inferiore. Aggiungere una trasposizione della tuberosità tibiale riduce parzialmente il malracking, senza correggerlo del tutto né migliorare i punteggi soggettivi.", "Studio monocentrico, retrospettivo, senza randomizzazione fra le strategie chirurgiche; tecnica di fissazione dell'MPFL e innesto non specificati nell'abstract. Utile comunque come primo passo verso una stratificazione preoperatoria: nei pazienti con torsione tibiale marcata o sperone sovratrocleare importante, l'MPFL isolata potrebbe non bastare."], "misto": ["In pazienti con instabilità ricorrente della rotula, esiste un segno clinico che può anticipare chi risponderà meno bene alla sola ricostruzione del legamento mediale patello-femorale (MPFL): la cosiddetta rotula «che salta» durante il movimento del ginocchio, invece di scorrere in modo regolare.", "In uno studio su 85 pazienti, questo segno era più frequente in presenza di specifiche alterazioni ossee — torsione della tibia, una prominenza sopra la troclea — e chi lo presentava prima dell'intervento ha ottenuto, dopo la sola ricostruzione dell'MPFL, punteggi funzionali più bassi e un rischio più alto di malracking persistente e nuova instabilità.", "I dati vengono da un solo centro cinese, con una tecnica di fissazione non descritta nel dettaglio: un'indicazione di rischio da conoscere, non una regola valida per ogni caso. Per il fisioterapista e il medico curante, un motivo in più per segnalare questo segno quando lo si osserva in visita."], "pazienti": ["Se la rotula si lussa più volte, un piccolo movimento anomalo osservabile durante la visita — la rotula che «salta» lateralmente invece di scorrere in modo regolare — può dire qualcosa in più sul tipo di intervento più adatto.", "In uno studio su pazienti con instabilità ricorrente della rotula, chi presentava questo segno prima dell'operazione ha avuto, dopo la sola ricostruzione del legamento principale, risultati meno soddisfacenti e un rischio più alto che la rotula tornasse a lussarsi.", "Riconoscerlo prima dell'intervento aiuta il chirurgo a decidere se, oltre alla ricostruzione del legamento, serva anche correggere l'osso sottostante. È uno studio su un gruppo specifico di pazienti: la valutazione del proprio caso resta sempre individuale."]}, "linkedin": {"chir": ["Non tutte le instabilità rotulee rispondono allo stesso modo alla ricostruzione isolata dell'MPFL. Una coorte retrospettiva su 85 pazienti (Beijing Jishuitan Hospital) isola il segno del jumping patella come marcatore prognostico preoperatorio, predetto in modo indipendente da torsione tibiale (OR 7,16; IC 95% 1,64-31,33) e sperone sovratrocleare (OR 30,5; IC 95% 6,95-133,77).", "\n\nAl follow-up, il gruppo jumping mostra Lysholm e Kujala significativamente più bassi, e più frequentemente lassità mediale (38% vs 22%), malracking residuo (55,6% vs 16,3%), persistenza del jumping (27,8% vs 2%), lassità dell'innesto (22,2% vs 4,1%) e ri-lussazione (13,9% vs 2%) — tutti p≤0,01. La trasposizione della tuberosità tibiale aggiunta riduce il malracking, non lo azzera, e non migliora i PROM.", "\n\nStudio retrospettivo, monocentrico, non randomizzato; fissazione MPFL e innesto non specificati. Resta un contributo utile alla pianificazione preoperatoria: il jumping patella preoperatorio, insieme a torsione tibiale e sperone sovratrocleare, può motivare di aggiungere un gesto osseo alla sola ricostruzione legamentosa."], "misto": ["Un piccolo segno osservabile alla visita — la rotula che «salta» invece di scorrere — potrebbe anticipare chi risponde meno bene alla sola ricostruzione del legamento mediale della rotula (MPFL). Uno studio cinese su 85 pazienti lo lega a specifiche alterazioni ossee della tibia e del femore.", "\n\nChi presentava questo segno prima dell'intervento ha avuto, dopo la sola MPFL, punteggi funzionali più bassi e più recidive di instabilità rispetto a chi aveva un movimento rotuleo regolare. Aggiungere una correzione ossea riduce parzialmente il problema, senza risolverlo del tutto.", "\n\nStudio monocentrico, tecnica di fissazione non dettagliata: un'indicazione utile per la pianificazione dell'intervento più che una regola generale, ma un motivo in più per una valutazione clinica e radiologica accurata prima di scegliere la strategia chirurgica."], "pazienti": ["Un movimento particolare della rotula durante la visita — invece di scorrere regolarmente, «salta» lateralmente — può aiutare il chirurgo a scegliere l'intervento più adatto in caso di instabilità ricorrente della rotula.", "\n\nUno studio su pazienti con questo segno mostra che, con la sola ricostruzione del legamento principale, i risultati sono meno soddisfacenti e il rischio di nuova lussazione più alto rispetto a chi non lo presenta.", "\n\nRiconoscerlo prima dell'intervento permette di valutare se aggiungere anche una correzione ossea. Ogni caso va comunque valutato singolarmente con il proprio chirurgo."]}, "instagram": {"chir": ["Jumping patella: un segno, un pronostico.\n\nCoorte retrospettiva, 85 pazienti, ricostruzione MPFL isolata a Pechino.", "\n\nPredittori: torsione tibiale (OR 7,16), sperone sovratrocleare (OR 30,5). Nel gruppo jumping: Lysholm e Kujala più bassi, più malracking, più ri-lussazioni (tutti p≤0,01).", "\n\nMonocentrico, non randomizzato, fissazione non specificata. Ma un tassello utile per la pianificazione preoperatoria."], "misto": ["La rotula che «salta» invece di scorrere: un segno che conta.\n\nUno studio su 85 pazienti lo lega a specifiche alterazioni ossee di tibia e femore.", "\n\nChi lo presenta prima dell'intervento ha, con la sola ricostruzione del legamento, risultati meno buoni e più recidive di instabilità.", "\n\nUn'indicazione utile per la pianificazione, non una regola assoluta: la valutazione clinica resta centrale."], "pazienti": ["Un piccolo segno alla visita può dire molto sulla rotula instabile.\n\nSe la rotula «salta» lateralmente invece di scorrere regolarmente, il chirurgo lo tiene in considerazione.", "\n\nUno studio mostra che, in questi casi, la sola ricostruzione del legamento può non bastare del tutto.", "\n\nRiconoscerlo prima aiuta a scegliere l'intervento giusto — sempre caso per caso."]}, "reel": {"chir": ["[Jumping patella: il segno che cambia la prognosi] Coorte di 85 pazienti, ricostruzione MPFL isolata, Pechino.", "[I predittori] Torsione tibiale OR 7,16, sperone sovratrocleare OR 30,5. Esiti peggiori nel gruppo jumping, tutti p≤0,01.", "[Per la pratica] Un segno da cercare in visita prima di decidere l'estensione del gesto chirurgico."], "misto": ["[La rotula che «salta»] Un segno clinico che anticipa chi risponde meno bene alla sola ricostruzione del legamento.", "[Cosa dice lo studio] Legato a specifiche alterazioni ossee; più recidive e punteggi più bassi se presente prima dell'intervento.", "[Perché conta] Aiuta a decidere se serve anche una correzione ossea, non solo il legamento."], "pazienti": ["[Un segno da non sottovalutare] Se la rotula «salta» invece di scorrere, può servire di più della sola ricostruzione del legamento.", "[Cosa cambia] Riconoscerlo prima dell'intervento aiuta a scegliere la strategia più adatta.", "[Il messaggio] Ogni caso è diverso: la valutazione resta sempre individuale con il proprio chirurgo."]}}, "4": {"video": {"chir": ["Una meta-analisi di 8 studi comparativi chiude, almeno per ora, l'entusiasmo intorno al templating preoperatorio con intelligenza artificiale in protesi totale di ginocchio: nelle analisi ristrette alla taglia effettivamente impiantata, il vantaggio sulla previsione esatta della componente femorale non raggiunge la significatività statistica.", "Il rischio relativo per la componente femorale è 1,38, ma con un intervallo di confidenza al 95% che va da 0,92 a 2,08 e un p di 0,09 — non significativo. Sulla tibiale il segnale è al limite (RR 1,38; IC 95% 1,01-1,89; p=0,05). Il planning 3D su TC assistito da IA fa meglio del templating radiografico convenzionale; il planning IA su sola radiografia resta inconcludente. Nessuna differenza sui punteggi funzionali a 3 mesi.", "Solo 8 studi, eterogenei per tecnologia e definizione di previsione esatta; impossibile isolare il contributo della sola componente IA da quello dell'imaging tridimensionale. Prima di investire in un modulo di templating IA aggiuntivo, vale la pena chiedersi se il guadagno reale non venga, semplicemente, dalla TC."], "misto": ["Sempre più software di pianificazione per la protesi di ginocchio promettono maggiore precisione grazie all'intelligenza artificiale. Una sintesi di 8 studi comparativi mette alla prova questa promessa sulla scelta della taglia dell'impianto.", "Il risultato: nessun vantaggio chiaramente dimostrato per la componente femorale (il miglioramento non è statisticamente significativo), un segnale appena percettibile per la tibiale. Il vantaggio più consistente si vede quando l'intelligenza artificiale lavora insieme a immagini tridimensionali della TC, non con la sola radiografia. Nessuna differenza sui risultati funzionali a breve termine.", "Con solo 8 studi diversi fra loro nella tecnologia usata, la sintesi indica una direzione di ricerca promettente, non un vantaggio già dimostrato e pronto per l'uso quotidiano. Un punto utile da conoscere prima di scegliere fra centri o strumenti che pubblicizzano il proprio planning «intelligente»."], "pazienti": ["Sempre più spesso si sente parlare di intelligenza artificiale applicata alla protesi di ginocchio, per esempio nella scelta della taglia giusta dell'impianto prima dell'intervento. Una revisione scientifica ha verificato se questa tecnologia funzioni davvero meglio di quella tradizionale.", "La risposta, a oggi, è prudente: non c'è una prova chiara che l'intelligenza artificiale, da sola, scelga la taglia in modo più preciso. Qualche vantaggio si vede solo quando è associata a una TC tridimensionale, non con la semplice radiografia. E i risultati per il paziente, a pochi mesi dall'intervento, restano sostanzialmente gli stessi.", "Non riguarda la sicurezza dell'intervento: la scelta finale della taglia viene comunque verificata e confermata dal chirurgo durante l'operazione, qualunque sia lo strumento di pianificazione usato prima."]}, "linkedin": {"chir": ["Templating IA in protesi di ginocchio: il beneficio sulla previsione esatta della taglia femorale non è statisticamente significativo (RR 1,38; IC 95% 0,92-2,08; p=0,09). Una meta-analisi di 8 studi comparativi (The Knee) lo dimostra, con un segnale al limite sulla tibiale (RR 1,38; IC 95% 1,01-1,89; p=0,05).", "\n\nIl planning 3D su TC assistito da IA supera il templating radiografico convenzionale; il planning IA su sola radiografia resta inconcludente. Nessuna differenza sui punteggi funzionali a 3 mesi. Il vantaggio osservato potrebbe riflettere l'effetto dell'imaging tridimensionale più che dell'algoritmo in sé.", "\n\nSolo 8 studi eterogenei, intervalli di previsione ampi in entrambi gli esiti principali: non è possibile isolare il contributo della sola IA. Utile da avere pronto in qualunque conversazione commerciale su moduli di templating IA proposti come miglioria autonoma."], "misto": ["Il templating con intelligenza artificiale è ormai proposto da diversi produttori per la protesi di ginocchio. Ma migliora davvero la scelta della taglia dell'impianto? Una sintesi di 8 studi risponde con cautela: non ancora, in modo dimostrato.", "\n\nIl vantaggio più consistente si vede solo quando l'IA lavora su immagini TC tridimensionali, non con la semplice radiografia — e anche in quel caso l'incertezza statistica resta ampia. Nessuna differenza sui risultati funzionali a breve termine.", "\n\nUn punto utile per orientarsi fra le proposte commerciali: la tecnologia promette bene, ma il beneficio dimostrato oggi resta limitato e probabilmente più legato all'imaging 3D che all'algoritmo stesso."], "pazienti": ["Alcuni centri offrono oggi la pianificazione della protesi di ginocchio con l'aiuto dell'intelligenza artificiale. Una revisione scientifica ha verificato se questo migliori davvero la scelta della taglia dell'impianto.", "\n\nLa risposta è prudente: non c'è ancora una prova chiara di un vantaggio netto. Qualche segnale positivo solo quando l'IA lavora insieme a una TC tridimensionale, non con la sola radiografia.", "\n\nNon riguarda la sicurezza dell'intervento: la taglia definitiva viene sempre verificata e confermata dal chirurgo durante l'operazione, con qualunque strumento di pianificazione."]}, "instagram": {"chir": ["Templating IA in protesi di ginocchio: promette, ma non dimostra (ancora).\n\nMeta-analisi di 8 studi, The Knee.", "\n\nFemorale: RR 1,38, IC 95% 0,92-2,08, p=0,09 — non significativo. Tibiale: al limite (p=0,05). Meglio solo se abbinato a TC 3D.", "\n\n8 studi eterogenei, intervalli ampi. Il beneficio potrebbe essere dell'imaging 3D, non dell'algoritmo."], "misto": ["L'intelligenza artificiale sceglie meglio la taglia della protesi di ginocchio?\n\nUna sintesi di 8 studi risponde: non ancora, in modo dimostrato.", "\n\nQualche vantaggio solo se abbinata a una TC 3D, non con la semplice radiografia. Nessuna differenza sui risultati a breve termine.", "\n\nLa tecnologia promette, il beneficio dimostrato oggi resta limitato."], "pazienti": ["L'intelligenza artificiale nella scelta della protesi di ginocchio: funziona già?\n\nUna revisione scientifica dice: non è ancora dimostrato.", "\n\nQualche segnale positivo solo insieme alla TC tridimensionale, non con la sola radiografia.", "\n\nLa taglia finale viene comunque sempre verificata dal chirurgo durante l'intervento."]}, "reel": {"chir": ["[Templating IA in TKA: dimostrato o no?] Meta-analisi di 8 studi, The Knee.", "[I numeri] Femorale RR 1,38 (p=0,09, NS). Tibiale al limite (p=0,05). Meglio solo con TC 3D.", "[Il punto] Il beneficio potrebbe essere dell'imaging 3D, non dell'algoritmo IA in sé."], "misto": ["[L'IA sceglie meglio la taglia della protesi?] Una sintesi di 8 studi dice: non ancora, in modo dimostrato.", "[Quando funziona un po' meglio] Solo se abbinata a una TC 3D, non con la sola radiografia.", "[Da ricordare] Promette bene, ma il beneficio provato oggi resta limitato."], "pazienti": ["[L'intelligenza artificiale nella protesi di ginocchio] Aiuta davvero a scegliere la taglia giusta? Non è ancora dimostrato.", "[Cosa dice la scienza] Qualche vantaggio solo insieme alla TC 3D, non con la radiografia semplice.", "[Da sapere] La taglia finale è comunque sempre verificata dal chirurgo durante l'operazione."]}}, "5": {"video": {"chir": ["Una coorte retrospettiva monocentrica di Pittsburgh (gruppo Musahl, UPMC Freddie Fu Sports Medicine Center) offre la finestra più lunga mai pubblicata sul trapianto di menisco da allograft: 160 pazienti, follow-up mediano di 15 anni, fino a 25. Sopravvivenza dell'innesto: 84% a 10 anni, 76% a 15, 69% a 20, 52% a 25.", "All'analisi univariata nessun fattore — età, sesso, BMI, fumo, tecnica di fissazione, stato cartilagineo, osteotomia associata — predice il fallimento. Ma dopo aggiustamento per età e grado cartilagineo del comparto trapiantato, il sesso femminile emerge come predittore indipendente (p=0,04). Il fallimento clinico, definito da un IKDC soggettivo sotto 56, riguarda il 40% dei pazienti e non è associato al fallimento strutturale dell'innesto (p=0,20).", "Il segnale sul sesso femminile emerge solo dopo aggiustamento statistico, non all'analisi univariata semplice — un dato meno solido di quanto sembri a prima lettura, e il razionale biologico non è discusso. Non è la tua tecnica: tu ripari il menisco o ne rifissi la radice. Ma è un riferimento a lungo termine dal gruppo che segui, utile nel colloquio col paziente che chiede di questa opzione vista altrove."], "misto": ["Quanto dura, davvero, un menisco trapiantato da donatore? Uno studio americano ha seguito 160 pazienti per una media di 15 anni, fino a un massimo di 25, per rispondere proprio a questa domanda.", "La sopravvivenza dell'innesto è dell'84% a 10 anni e del 76% a 15, con un calo progressivo nei decenni successivi. Nessun fattore di rischio chiaro emerge a un primo sguardo, ma un'analisi più approfondita suggerisce che le pazienti donne potrebbero avere un rischio leggermente più alto di fallimento — un segnale da confermare, non da dare per certo.", "Non è una tecnica eseguita in questo studio (qui si preferisce riparare il menisco o rifissarne la radice, quando possibile), ma è un'informazione preziosa per chi valuta questa opzione altrove, o per il medico curante che accompagna un paziente già trapiantato anni fa."], "pazienti": ["Il trapianto di menisco da donatore è un'opzione chirurgica diversa dalla più comune riparazione del menisco. Uno studio americano ha seguito per molti anni un gruppo di pazienti trapiantati per capire quanto duri davvero questo intervento nel tempo.", "I risultati sono incoraggianti nel medio periodo — la maggior parte degli innesti funziona bene a 10 e anche a 15 anni di distanza — con un calo naturale dell'efficacia negli anni successivi, come per molte soluzioni chirurgiche di questo tipo.", "Non è una tecnica che utilizziamo in questo studio della nostra pratica, dove privilegiamo la riparazione del menisco quando possibile. Ma è un'informazione utile per chi si informa su questa opzione, da discutere sempre con lo specialista di riferimento."]}, "linkedin": {"chir": ["Il follow-up più lungo mai pubblicato sul trapianto di menisco da allograft: coorte di Pittsburgh (Musahl, UPMC Freddie Fu Center), 160 pazienti, follow-up mediano 15 anni (fino a 25). Sopravvivenza dell'innesto: 84% a 10 anni, 76% a 15, 69% a 20, 52% a 25.", "\n\nAll'analisi univariata nessun fattore di rischio raggiunge la significatività. Dopo aggiustamento per età e grado cartilagineo, il sesso femminile emerge come predittore indipendente di fallimento (p=0,04) — un segnale statisticamente presente ma fragile, non confermato alla semplice analisi univariata. Il fallimento clinico (IKDC<56, 40% dei pazienti) non è associato al fallimento strutturale (p=0,20).", "\n\nNon è una tecnica che eseguiamo nella nostra pratica — qui si preferisce la riparazione meniscale o la rifissazione della radice — ma è materiale di conoscenza rilevante dal gruppo Musahl/Freddie Fu che seguiamo come riferimento per il menisco a lungo termine, utile nel colloquio col paziente che valuta questa opzione altrove."], "misto": ["Quanto dura un trapianto di menisco da donatore? Una coorte americana lo segue per una media di 15 anni, fino a 25: la risposta è «a lungo, ma non per sempre».", "\n\nSopravvivenza dell'innesto: 84% a 10 anni, 76% a 15, con calo progressivo negli anni successivi. Nessun fattore di rischio chiaro all'analisi semplice, ma un segnale — da confermare — che le pazienti donne potrebbero avere un rischio leggermente più alto di fallimento.", "\n\nNon è una tecnica eseguita nella nostra pratica abituale, dove si preferisce riparare il menisco quando possibile, ma è un'informazione utile per orientare pazienti e colleghi su questa opzione chirurgica."], "pazienti": ["Il trapianto di menisco da donatore funziona bene per molti anni — lo dice uno studio americano che ha seguito pazienti trapiantati fino a 25 anni dopo l'intervento.", "\n\nLa maggior parte degli innesti funziona ancora bene a 10 e 15 anni di distanza, con un calo naturale negli anni successivi, come accade per molte soluzioni chirurgiche di lunga durata.", "\n\nNon è una tecnica che utilizziamo in questo studio della nostra pratica — qui si privilegia la riparazione del menisco quando possibile — ma un'informazione utile per chi la valuta altrove, da discutere sempre con il proprio specialista."]}, "instagram": {"chir": ["Trapianto di menisco da allograft: quanto dura davvero?\n\nCoorte di Pittsburgh (Musahl), 160 pazienti, follow-up fino a 25 anni.", "\n\nSopravvivenza: 84% a 10 anni, 76% a 15, 52% a 25. Il sesso femminile emerge come fattore di rischio solo dopo aggiustamento statistico (p=0,04) — segnale fragile.", "\n\nNon è la nostra tecnica (qui si ripara il menisco), ma un riferimento utile dal gruppo che seguiamo per il menisco a lungo termine."], "misto": ["Quanto dura un trapianto di menisco?\n\nUno studio americano lo segue fino a 25 anni: a lungo, ma non per sempre.", "\n\n84% di sopravvivenza a 10 anni, 76% a 15. Le donne potrebbero avere un rischio leggermente più alto — dato da confermare.", "\n\nNon è la tecnica che usiamo qui abitualmente, ma utile da sapere per chi la valuta."], "pazienti": ["Il trapianto di menisco funziona bene per molti anni.\n\nUno studio americano lo dimostra fino a 25 anni di distanza dall'intervento.", "\n\nCon il tempo l'efficacia cala un po', come per molte soluzioni chirurgiche — è normale, non un fallimento improvviso.", "\n\nNella nostra pratica si preferisce riparare il menisco quando possibile: ne parliamo insieme, caso per caso."]}, "reel": {"chir": ["[Trapianto di menisco: quanto dura?] Coorte di Pittsburgh, 160 pazienti, follow-up fino a 25 anni.", "[I numeri] Sopravvivenza 84% a 10 anni, 76% a 15. Sesso femminile: fattore di rischio solo dopo aggiustamento (p=0,04).", "[Per la pratica] Non la nostra tecnica, ma un riferimento utile a lungo termine sul menisco."], "misto": ["[Un trapianto di menisco dura per sempre?] No — ma può durare a lungo, mostra uno studio a 25 anni.", "[I dati] 84% funziona ancora a 10 anni, 76% a 15. Nelle donne il rischio potrebbe essere un po' più alto.", "[Da sapere] Qui si preferisce riparare il menisco quando possibile."], "pazienti": ["[Il trapianto di menisco funziona a lungo?] Sì, mostra uno studio che arriva fino a 25 anni dopo l'intervento.", "[Cosa succede nel tempo] L'efficacia cala un po' con gli anni — è normale, non un allarme.", "[Nella nostra pratica] Si preferisce riparare il menisco quando possibile: se ne parla insieme, caso per caso."]}}};
var TAGS={"1": {"linkedin": "#RoboticSurgery #OrthopaedicInnovation #AIinMedicine", "instagram": "#ChirurgiaRobotica #Ginocchio #IntelligenzaArtificiale #Ortopedia #Innovazione #ProtesiGinocchio #VELYS #Ricerca #MedicinaDelFuturo", "kw": "chirurgia robotica ginocchio, intelligenza artificiale ortopedia, protesi robotica VELYS"}, "2": {"linkedin": "#ACLRecovery #SportsMedicine #FootballInjuries", "instagram": "#LCA #Ginocchio #Calcio #Calciatori #ChirurgiaOrtopedica #MedicinaSportiva #RitornoAlloSport #Legamenti #Ortopedia", "kw": "recupero crociato calciatori, ritorno in campo dopo LCA, carriera sportiva dopo infortunio"}, "3": {"linkedin": "#PatellarInstability #MPFLReconstruction #KneeSurgery", "instagram": "#Rotula #Ginocchio #InstabilitàRotulea #ChirurgiaOrtopedica #MPFL #Ortopedia #MedicinaSportiva #Legamenti #Ricerca", "kw": "instabilità rotulea intervento, ricostruzione legamento rotula, lussazione rotula ginocchio"}, "4": {"linkedin": "#TotalKneeArthroplasty #AIinSurgery #OrthopaedicResearch", "instagram": "#ProtesiGinocchio #IntelligenzaArtificiale #ChirurgiaOrtopedica #Ortopedia #Innovazione #Ricerca #MedicinaDelFuturo #Artroplastica #Ginocchio", "kw": "protesi ginocchio pianificazione digitale, intelligenza artificiale chirurgia ortopedica, taglia protesi ginocchio"}, "5": {"linkedin": "#MeniscalTransplant #KneeSurgery #SportsMedicine", "instagram": "#Menisco #Ginocchio #TrapiantoMenisco #ChirurgiaOrtopedica #Ortopedia #MedicinaSportiva #Legamenti #Ricerca #SaluteArticolare", "kw": "trapianto menisco allograft, durata trapianto menisco, chirurgia ginocchio menisco"}};
var NLB={"1": {"prof": ["Intelligenza artificiale nei robot ortopedici: assistenza di precisione, non ancora autonomia", "Una revisione narrativa esamina sei piattaforme robotiche commerciali per la chirurgia ortopedica — incluso il sistema VELYS in uso nella nostra pratica — e conclude che nessuna soddisfa oggi i criteri tecnici di una reale intelligenza artificiale «incarnata», capace di percepire, ragionare e adattarsi in autonomia. Tutte restano tecnologie di assistenza di precisione: migliorano l'accuratezza del posizionamento e il flusso di lavoro, ma la decisione clinica resta interamente del chirurgo.", "Revisione narrativa, non sistematica, senza dati clinici originali: la sintesi è utile per calibrare le aspettative su ciò che questi sistemi sanno davvero fare oggi, non per un giudizio comparativo fra piattaforme."], "mix": ["Chirurgia robotica del ginocchio: precisa, ma non ancora «intelligente» da sola", "Una rassegna scientifica ha confrontato sei sistemi robotici usati oggi in chirurgia ortopedica, compreso quello impiegato nel nostro studio per le protesi di ginocchio. La conclusione: questi robot aiutano a posizionare l'impianto con grande precisione, ma non decidono da soli — restano strumenti guidati interamente dal chirurgo, non sistemi realmente autonomi o «intelligenti» nel senso tecnico del termine.", "È un'analisi di sintesi, non uno studio su pazienti: serve a distinguere la comunicazione commerciale intorno alla «chirurgia robotica intelligente» da ciò che la tecnologia sa fare oggi."], "paz": ["Il robot in sala operatoria aiuta il chirurgo, non lo sostituisce", "Una pubblicazione scientifica ha analizzato i sistemi robotici usati oggi nella chirurgia del ginocchio, compreso quello impiegato nel nostro studio per l'impianto delle protesi. Il messaggio è rassicurante e onesto insieme: questi strumenti aiutano il chirurgo a posizionare la protesi con grande precisione, ma ogni decisione resta sua — il robot esegue, non decide.", "Non è uno studio su pazienti operati, ma una rassegna di ciò che la tecnologia robotica sa fare oggi: utile per capire che «robot» non significa «automatico»."], "kw": "chirurgia robotica ginocchio, intelligenza artificiale ortopedia"}, "2": {"prof": ["Dopo il LCA, il rientro in campo non racconta tutta la carriera del calciatore", "Una coorte retrospettiva su 132 lesioni del legamento crociato anteriore in 115 calciatori professionisti spagnoli mostra un rientro in campo nel 97,7% dei casi, ma un declino sostanziale della carriera nel tempo: il 35,2% scende di categoria già nella prima stagione (61,3% alla quinta), i minuti giocati calano del 46% nella prima stagione (p<0,001) e il valore di mercato si riduce fino al 47,7% a 5 anni, soprattutto negli atleti più anziani.", "Studio retrospettivo senza gruppo di controllo di non infortunati: non separa il declino fisiologico di carriera dall'effetto specifico della lesione, e non riporta né tipo di innesto né tecnica chirurgica."], "mix": ["Tornare in campo dopo il crociato non significa tornare al livello di prima", "In un gruppo di 115 calciatori professionisti spagnoli operati di legamento crociato anteriore, quasi tutti sono tornati a giocare (97,7%), in media dopo 9 mesi. Ma seguendoli fino a 5 anni, un giocatore su tre gioca in una categoria inferiore già dal primo anno, i minuti in campo calano sensibilmente e il valore di mercato scende in modo marcato, soprattutto oltre i 30 anni.", "Mancano un gruppo di confronto e i dettagli sulla tecnica chirurgica: il messaggio pratico riguarda le aspettative, non la scelta dell'intervento."], "paz": ["Tornare a giocare dopo l'intervento al crociato è possibile, ma richiede tempo e aspettative realistiche", "Uno studio su calciatori professionisti spagnoli operati al legamento crociato anteriore del ginocchio conferma che quasi tutti riescono a tornare in campo, in media dopo circa nove mesi. Con gli anni, però, molti giocano un po' meno e a un livello leggermente inferiore rispetto a prima dell'infortunio — un percorso che riguarda anche gli sportivi non professionisti, seppure con numeri diversi.", "Riguarda calciatori professionisti di alto livello: il percorso di recupero di ogni paziente va valutato caso per caso con il proprio chirurgo."], "kw": "recupero legamento crociato calciatori, ritorno in campo dopo LCA"}, "3": {"prof": ["Il segno del «jumping» identifica i pazienti a rischio dopo ricostruzione dell'MPFL", "In una coorte retrospettiva di 85 pazienti con instabilità rotulea ricorrente, la torsione tibiale (OR 7,16) e lo sperone sovratrocleare (OR 30,5) predicono in modo indipendente il segno preoperatorio del «jumping patella». Chi presenta questo segno ha, dopo ricostruzione isolata dell'MPFL, punteggi Lysholm e Kujala significativamente più bassi e tassi più alti di malracking residuo, lassità dell'innesto e ri-lussazione rispetto a chi ha un pattern di scorrimento normale.", "Studio retrospettivo monocentrico senza randomizzazione fra le strategie chirurgiche; tecnica di fissazione e innesto non specificati — la trasferibilità alla propria tecnica va valutata caso per caso."], "mix": ["Un segno all'esame clinico anticipa chi rischia di più dopo la ricostruzione della rotula", "In pazienti con instabilità ricorrente della rotula, uno specifico comportamento della rotula durante il movimento del ginocchio — la cosiddetta «rotula che salta» — è più frequente quando ci sono alterazioni ossee specifiche (torsione della tibia, una prominenza sopra la troclea). Chi presenta questo segno prima dell'intervento ottiene, dopo la sola ricostruzione del legamento mediale patello-femorale, risultati funzionali meno buoni e un rischio più alto di nuova instabilità.", "I dati vengono da un solo centro e da una tecnica di fissazione non descritta nel dettaglio: sono un'indicazione di rischio, non una regola valida per ogni caso."], "paz": ["Un segno visibile durante la visita può aiutare a scegliere l'intervento giusto per la rotula instabile", "In alcuni pazienti con episodi ripetuti di lussazione della rotula, uno specifico movimento anomalo della rotula durante la flessione del ginocchio segnala un rischio più alto che la sola ricostruzione del legamento non basti a stabilizzarla del tutto. Riconoscerlo prima dell'intervento aiuta il chirurgo a decidere se aggiungere altri gesti correttivi.", "È uno studio su un gruppo specifico di pazienti in un centro cinese: la valutazione del proprio caso resta individuale."], "kw": "instabilità rotulea intervento, ricostruzione legamento rotula"}, "4": {"prof": ["Il planning con intelligenza artificiale non supera ancora il templating tradizionale nella protesi di ginocchio", "Una meta-analisi di 8 studi comparativi mostra che il templating preoperatorio assistito da intelligenza artificiale non migliora in modo statisticamente significativo la previsione esatta della taglia della componente femorale (RR 1,38; IC 95% 0,92-2,08; p=0,09), con un segnale al limite della significatività per la componente tibiale (RR 1,38; IC 95% 1,01-1,89; p=0,05). Il vantaggio più consistente emerge quando il planning IA si basa su immagini TC tridimensionali, non su sola radiografia.", "Solo 8 studi eterogenei per tecnologia; l'ampiezza degli intervalli di previsione lascia incertezza reale sull'entità del beneficio, e non è possibile isolare il contributo dell'IA da quello dell'imaging 3D."], "mix": ["L'intelligenza artificiale aiuta a scegliere la taglia della protesi di ginocchio? Ancora non è dimostrato", "Una sintesi di 8 studi ha confrontato i software di pianificazione con intelligenza artificiale con la pianificazione tradizionale nella scelta della taglia della protesi di ginocchio. Il risultato: nessun vantaggio chiaro e dimostrato, soprattutto quando l'IA lavora su semplici radiografie; qualche segnale di maggiore precisione solo quando è associata a immagini TC tridimensionali.", "Gli studi inclusi sono pochi e diversi fra loro nella tecnologia usata: la sintesi indica una direzione di ricerca, non un vantaggio già provato da adottare."], "paz": ["L'intelligenza artificiale nella scelta della taglia della protesi: ancora in fase di studio", "Alcuni programmi di pianificazione della protesi di ginocchio usano oggi l'intelligenza artificiale per aiutare a scegliere la taglia dell'impianto più adatta. Una revisione degli studi disponibili conclude che questi strumenti, da soli, non hanno ancora dimostrato di funzionare meglio della pianificazione tradizionale: il chirurgo continua a basarsi sulla propria esperienza e sulle immagini radiografiche o TC del paziente.", "Non riguarda la sicurezza dell'intervento, solo la fase di programmazione preoperatoria: la scelta della taglia viene comunque verificata e confermata durante l'operazione."], "kw": "protesi ginocchio pianificazione digitale, intelligenza artificiale chirurgia"}, "5": {"prof": ["Il trapianto di menisco da allograft: sopravvivenza buona ma non permanente, il sesso femminile come possibile fattore di rischio", "Una coorte retrospettiva di Pittsburgh su 160 pazienti seguiti fino a 25 anni riporta una sopravvivenza dell'innesto dell'84% a 10 anni, 76% a 15, 69% a 20 e 52% a 25. Nessun fattore risulta associato al fallimento all'analisi univariata, ma dopo aggiustamento per età e stato cartilagineo il sesso femminile emerge come predittore indipendente (p=0,04) — un segnale statisticamente fragile, da confermare, non da estremizzare nel colloquio col paziente.", "Il fallimento clinico (IKDC<56 nel 40% dei pazienti) non è risultato associato al fallimento strutturale dell'innesto: due esiti che in questa coorte non si allineano, con un campione di eventi limitato."], "mix": ["Il trapianto di menisco dura a lungo, ma non per sempre — e forse un po' meno nelle donne", "Uno studio americano su 160 pazienti trapiantati di menisco, seguiti in media per 15 anni, mostra una sopravvivenza dell'innesto dell'84% a 10 anni e del 76% a 15, con un calo progressivo negli anni successivi. Un'analisi più approfondita suggerisce che le pazienti donne potrebbero avere un rischio leggermente più alto di fallimento dell'innesto, ma il dato emerge solo dopo aggiustamenti statistici e va confermato da altri studi.", "Non è una tecnica eseguita in questo studio della nostra pratica (qui si preferisce riparare il menisco, non trapiantarlo), ma è utile per orientare i pazienti che chiedono informazioni su questa opzione vista altrove."], "paz": ["Il trapianto di menisco funziona bene per molti anni, ma non è una soluzione definitiva", "Uno studio a lungo termine su pazienti sottoposti a trapianto di menisco (una procedura diversa dalla riparazione del menisco più comunemente usata) mostra buoni risultati anche a 10-15 anni di distanza, con un calo naturale dell'efficacia negli anni successivi. È un dato utile per chi valuta questa opzione, da discutere caso per caso con lo specialista.", "Questo intervento non fa parte delle tecniche più usate nella nostra pratica, dove si preferisce la riparazione o la rifissazione del menisco quando possibile."], "kw": "trapianto menisco allograft, durata trapianto menisco"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"orange",sec:"res",j:"Journal of Robotic Surgery",h:"L'intelligenza artificiale nei robot ortopedici non è ancora autonoma",v:"Revisione narrativa su sei piattaforme commerciali, VELYS compreso: precisione di posizionamento migliorata, ma nessuna è davvero «intelligente» o adattiva — restano tecnologie di assistenza di precisione, non sistemi che percepiscono e imparano da soli.",ax:"Özdemir, Özdeş",date:"set 2026",meta:"revisione narrativa, 6 piattaforme commerciali (MAKO, ROSA, CORI/NAVIO, VELYS, ExcelsiusGPS, TSolution One) · [V]",pmid:'42678638',doi:'10.1007/s11701-026-03913-5',journal:"Journal of Robotic Surgery",authors:"Özdemir E, Özdeş HU",design:"Revisione narrativa strutturata (non sistematica) sullo stato dell'arte dei sistemi robotici ortopedici commerciali e sul potenziale della cosiddetta «intelligenza artificiale incarnata» (Embodied AI) — sistemi capaci di percepire, ragionare e adattarsi in tempo reale, non solo eseguire un piano preimpostato.",pop:"Non uno studio clinico: analisi comparativa di sei piattaforme in commercio — MAKO (Stryker), ROSA (Zimmer Biomet), CORI/NAVIO (Smith+Nephew), VELYS (DePuy Synthes), ExcelsiusGPS (Globus Medical), TSolution One (THINK Surgical) — su autonomia, capacità adattiva e funzionalità clinica, con applicazioni discusse in artroplastica, trauma, colonna e oncologia ortopedica.",results:"Nessun dato clinico quantitativo: gli autori concludono che tutti i sistemi commerciali attuali, VELYS compreso, restano tecnologie di «assistenza di precisione» — migliorano accuratezza di impianto, posizionamento e flusso di lavoro documentati in letteratura — ma nessuno è realmente «incarnato» o autonomo secondo la definizione tecnica usata nel testo (percezione-ragionamento-azione in ciclo continuo, apprendimento continuo, gemelli digitali paziente-specifici).",concl:"Gli autori sostengono che il salto verso un'autonomia adattiva reale richiede l'integrazione di visione artificiale, modelli fondazionali, apprendimento per rinforzo e gemelli digitali, insieme a validazione multicentrica, standard regolatori e — esplicitamente — un sistema «human-in-command» che mantenga il chirurgo al comando.",limits:"Revisione narrativa, non sistematica: nessun protocollo dichiarato, selezione delle fonti non riproducibile · nessun dato clinico originale, solo sintesi di funzionalità dichiarate dai produttori e dalla letteratura esistente · due soli autori, nessuna dichiarazione di conflitto di interesse riportata nell'abstract.",perte:"Non cambia nulla nella tua pratica di domani, ma inquadra con onestà un punto che riguarda direttamente il VELYS che usi: anche la piattaforma più recente resta, per gli standard di questa revisione, uno strumento di precisione assistita — non un sistema che «decide» o «impara» da solo. Utile per il tuo interesse dichiarato su intelligenza artificiale e automazione in sanità: la differenza fra il marketing dei sistemi robotici e la loro reale autonomia tecnica è precisamente la distinzione che vale la pena portare in una conversazione con pazienti o colleghi entusiasti di «chirurgia robotica intelligente»."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Knee Surgery & Related Research",h:"Dopo il LCA, i calciatori professionisti tornano ma giocano meno",v:"Coorte retrospettiva su 132 lesioni del LCA in 115 calciatori spagnoli di Prima Divisione: rientro in campo nel 97,7% dei casi, ma un giocatore su tre scende di categoria entro un anno e il valore di mercato cala fino al 47,7% a 5 anni.",ax:"Montiel … Valentí",date:"set 2026",meta:"coorte retrospettiva, dati pubblici incrociati con referti medici · 132 lesioni LCA in 115 calciatori professionisti · [IV]",pmid:'42698107',doi:'10.1186/s43019-026-00346-0',journal:"Knee Surgery & Related Research",authors:"Montiel V, Álvarez García H, Ramirez NA, Mateo N, Valentí A",design:"Studio di coorte retrospettivo su calciatori professionisti maschi della Prima Divisione spagnola, identificati tramite database pubblici (Transfermarkt, BeSoccer) e verificati con referti medici ufficiali o fonti giornalistiche. Segue minuti giocati, livello di campionato e valore di mercato fino a 5 anni dopo l'infortunio.",pop:"132 lesioni del LCA in 115 calciatori professionisti, stagioni 2010-11–2023-24. Età media all'infortunio 26,7 anni. Nessun dettaglio riportato su tipo di innesto o tecnica chirurgica.",results:"Rientro in campo: 97,7%, tempo medio 9,1 mesi; prima presenza in gara mediana 13,5 giorni dopo il rientro in gruppo squadra. Il 35,2% scende di almeno un livello di campionato già nella prima stagione dopo l'infortunio, quota che sale al 61,3% alla quinta stagione. Minuti giocati: -46% nella prima stagione post-infortunio (p<0,001), recupero solo parziale in seguito; i minuti per partita restano circa 21 minuti sotto i valori pre-infortunio per due stagioni intere (p<0,001 in entrambe). Valore di mercato: calo significativo lungo tutto il follow-up, fino al 47,7% a 5 anni, più marcato negli atleti ≥30 anni.",concl:"Gli autori concludono che, nonostante un tasso di rientro in campo molto alto, i calciatori professionisti mostrano riduzioni longitudinali di minuti giocati, livello competitivo e valore di mercato — la sola percentuale di rientro in campo sovrastima il reale recupero della carriera.",limits:"Nessun gruppo di controllo di calciatori non infortunati per separare il declino fisiologico di carriera dall'effetto specifico dell'infortunio · i dati di mercato (Transfermarkt) sono stime, non transazioni verificate · nessun dato su tipo di innesto, tecnica chirurgica o presenza di tenodesi laterale · popolazione maschile, Prima Divisione spagnola: trasferibilità ad altri campionati o al calcio femminile non verificata.",perte:"Non riguarda una tua tecnica specifica, ma tocca un tema che alimenta la divulgazione e il colloquio con pazienti atleti: il «rientro in campo» al 97,7% racconta solo metà della storia. Utile per calibrare le aspettative dei pazienti sportivi di alto livello — specie professionisti o semi-professionisti — oltre la sola domanda «tornerò a giocare?»."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Knee Surgery & Related Research",h:"La «rotula che salta» predice esiti peggiori dopo MPFL",v:"Coorte retrospettiva su 85 pazienti con instabilità rotulea ricorrente: torsione tibiale e sperone sovratrocleare predicono il segno del «jumping», che si associa a punteggi funzionali più bassi e più recidive dopo ricostruzione dell'MPFL.",ax:"Wang … Zhang",date:"set 2026",meta:"coorte retrospettiva comparativa, monocentrica (Pechino) · 85 pazienti (36 jumping, 49 gliding) · [III]",pmid:'42698120',doi:'10.1186/s43019-026-00347-z',journal:"Knee Surgery & Related Research",authors:"Wang D, Liu Y, Tang Z, Zhang Z, Zhang H",design:"Studio di coorte retrospettivo monocentrico (Beijing Jishuitan Hospital), 2018-2022: pazienti con lussazione rotulea ricorrente sottoposti a ricostruzione dell'MPFL, stratificati in base alla presenza preoperatoria del segno del «jumping» (rotula che salta lateralmente durante il movimento) contro pattern di scorrimento («gliding») normale. TC ginocchio-anca-caviglia per la morfologia ossea; regressione logistica multivariata per i fattori di rischio; confronto degli esiti clinici al follow-up finale.",pop:"85 pazienti con lussazione rotulea ricorrente sottoposti a ricostruzione dell'MPFL: 36 con segno del jumping preoperatorio, 49 con pattern gliding.",results:"Fattori di rischio indipendenti per il jumping: torsione tibiale (OR 7,16; IC 95% 1,64-31,33; p=0,009) e sperone sovratrocleare (OR 30,5; IC 95% 6,95-133,77; p<0,001). Al follow-up finale il gruppo jumping ha punteggi peggiori — Lysholm 75,7 contro 86,1 (p=0,002), Kujala 80,8 contro 89,9 (p=0,003) — e più frequentemente lassità mediale della rotula (38% contro 22%; p=0,001), malracking residuo (55,6% contro 16,3%; p<0,001), persistenza del segno del jumping (27,8% contro 2%; p<0,001), lassità dell'innesto MPFL (22,2% contro 4,1%; p=0,01) e ri-lussazione (13,9% contro 2%; p=0,035).",concl:"Gli autori concludono che la rotula «jumping» identifica un sottogruppo a rischio più alto di esito peggiore dopo ricostruzione isolata dell'MPFL; la trasposizione della tuberosità tibiale aggiunta riduce parzialmente il malracking residuo e le recidive, ma non lo corregge completamente né migliora i punteggi soggettivi.",limits:"Studio retrospettivo, singolo centro, nessuna randomizzazione fra le strategie chirurgiche (isolata vs combinata con trasposizione) · numerosità dei sottogruppi non dettagliata per il confronto dei punteggi riferiti dal paziente · tecnica di fissazione MPFL e materiale d'innesto non specificati nell'abstract · popolazione cinese monocentrica, trasferibilità non verificata.",perte:"Riguarda direttamente la tua area chirurgica — la ricostruzione dell'MPFL — anche se tecnica di fissazione e popolazione non coincidono con la tua pratica (ancore FiberTak, tecnica onlay). Il messaggio pratico: nei pazienti con torsione tibiale marcata o sperone sovratrocleare importante, il segno del jumping preoperatorio segnala un rischio più alto di esito insoddisfacente con la sola MPFL isolata — un elemento in più da valutare nella pianificazione di eventuali gesti ossei associati."},{n:4,mono:"m-knee",dot:"green",sec:"res",j:"The Knee",h:"Il templating con IA non batte quello tradizionale in protesi di ginocchio",v:"Revisione sistematica e meta-analisi di 8 studi: il templating preoperatorio assistito da IA non migliora in modo significativo la previsione esatta della taglia femorale, e il beneficio sulla tibiale resta incerto.",ax:"Jancevski … Martins",date:"set 2026",meta:"revisione sistematica e meta-analisi · 8 studi comparativi · [II]",pmid:'42685462',doi:'10.1016/j.knee.2026.104618',journal:"The Knee",authors:"Jancevski T, Mora L, Borse AM, García Cortés DA, Martins EC",design:"Revisione sistematica e meta-analisi (PubMed/MEDLINE, Scopus, Web of Science, Cochrane Library, dall'origine a novembre 2025) di studi che confrontano il templating preoperatorio assistito da intelligenza artificiale con il templating convenzionale nella previsione esatta della taglia di componente femorale e tibiale in protesi totale di ginocchio primaria. Rischio di bias valutato con RoB 2 e ROBINS-I.",pop:"8 studi comparativi su protesi totale di ginocchio primaria; numero complessivo di pazienti non aggregato nell'abstract.",results:"Nelle analisi ristrette alla taglia effettivamente impiantata, il templating IA non migliora in modo significativo la previsione esatta della componente femorale (RR 1,38; IC 95% 0,92-2,08; p=0,09; intervallo di previsione al 95% 0,63-3,04); il miglioramento sulla componente tibiale è al limite della significatività (RR 1,38; IC 95% 1,01-1,89; p=0,05; intervallo di previsione 0,76-2,49). Il planning 3D basato su TC assistito da IA mostra accuratezza superiore al templating radiografico convenzionale; il planning su sola radiografia con IA resta inconcludente. Nessuna differenza significativa sui punteggi funzionali a 3 mesi.",concl:"Gli autori concludono che il planning 3D su TC potrebbe migliorare la previsione esatta della taglia, ma l'ampiezza dell'intervallo di previsione lascia incertezza su consistenza ed entità del beneficio; il vantaggio osservato potrebbe riflettere l'effetto combinato dell'imaging tridimensionale e della componente IA, non l'IA da sola.",limits:"Solo 8 studi inclusi, eterogenei per tecnologia (planning 2D-radiografico vs 3D-TC) e per definizione di «previsione esatta» · intervallo di previsione al 95% che attraversa l'assenza di effetto in entrambi gli esiti principali · nessun dato clinico a lungo termine, solo esiti funzionali a 3 mesi · impossibile isolare il contributo della sola IA da quello dell'imaging 3D.",perte:"Attinente al tuo interesse per l'intelligenza artificiale applicata alla medicina e per la pianificazione digitale in artroplastica robotica: prima di adottare o raccomandare uno strumento di templating IA per la taglia della componente, questa sintesi dice che il beneficio dimostrato oggi è incerto e probabilmente legato più all'imaging 3D che all'algoritmo in sé — un punto utile in una conversazione commerciale con un fornitore che proponga il proprio modulo IA come miglioria autonoma."},{n:5,mono:"m-gray",dot:"gray",sec:"res",j:"American Journal of Sports Medicine",h:"Il trapianto di menisco da allograft dura meno nelle donne",v:"Coorte di Pittsburgh (gruppo Musahl) su 160 pazienti seguiti fino a 25 anni: sopravvivenza dell'innesto 84% a 10 anni, 76% a 15; dopo aggiustamento statistico il sesso femminile emerge come predittore di fallimento.",ax:"Park … Hughes",date:"ago 2026",meta:"coorte retrospettiva monocentrica (Pittsburgh) · 160 pazienti, follow-up mediano 15 anni · [III]",pmid:'42578469',doi:'10.1177/03635465261470172',journal:"American Journal of Sports Medicine",authors:"Park YL, Wackerle AM, Jiang C, Vieider RP, Winkler PW, Irrgang JJ, Musahl V, Hughes JD",design:"Studio di coorte retrospettivo monocentrico (UPMC Freddie Fu Sports Medicine Center, Pittsburgh): tutti i pazienti sottoposti a trapianto di menisco da allograft (fissazione a blocco osseo o solo tessuto molle) fra il 1993 e il 2020, esclusi i follow-up <5 anni e le lesioni cartilaginee di grado 4 non trattate. Sopravvivenza dell'innesto con Kaplan-Meier; regressione di Cox univariata per i fattori di rischio.",pop:"160 pazienti (57% della popolazione screenata), 46% donne, età mediana all'intervento 28 anni, follow-up mediano 15 anni (range interquartile 10-21 anni).",results:"43 fallimenti dell'innesto durante il follow-up. Sopravvivenza dell'innesto: 84% a 10 anni, 76% a 15, 69% a 20, 52% a 25. All'analisi univariata nessun fattore — età, sesso, indice di massa corporea, fumo, tecnica di fissazione, stato cartilagineo, osteotomia associata — è risultato significativamente associato al fallimento (tutti p>0,05). Dopo aggiustamento per età e grado cartilagineo del comparto trapiantato, il sesso femminile è diventato un predittore significativo di fallimento dell'innesto (p=0,04). Fallimento clinico (punteggio IKDC soggettivo <56 al follow-up finale) in 32 pazienti (40%), non associato al fallimento dell'innesto (p=0,20). Nessuna differenza significativa negli esiti riferiti dal paziente fra uomini e donne (p>0,05).",concl:"Gli autori concludono che il trapianto di menisco da allograft ha una sopravvivenza dell'84% a 10 anni con declino graduale nel tempo, e che il sesso femminile emerge come predittore di fallimento dopo aggiustamento per età e stato cartilagineo — utile per la selezione del paziente e il colloquio sulle aspettative a lungo termine.",limits:"L'associazione col sesso femminile emerge solo dopo aggiustamento statistico, non alla semplice analisi univariata: un segnale meno solido di quanto sembri a prima lettura · il fallimento clinico non è associato al fallimento strutturale dell'innesto, con soli 32/160 eventi clinici il confronto resta debole · studio monocentrico, retrospettivo, coorte selezionata (57% della popolazione screenata originale, criteri di esclusione non completamente dettagliati nell'abstract).",perte:"Non è una tecnica che esegui — tu ripari il menisco o ne rifissi la radice, non trapianti allograft — ma è materiale di conoscenza sul menisco a lungo termine, dal gruppo di Pittsburgh (Musahl, la scuola di Freddie Fu) che segui come riferimento. Il messaggio, per il paziente che ti chiede di un trapianto di menisco visto altrove: sopravvivenza buona ma non permanente, e il sesso femminile potrebbe pesare più di quanto si pensasse nella selezione — un segnale statisticamente fragile, da non sovrainterpretare."}];
var SUGGQ=[{"k": "kol", "n": "Kostas J. Economopoulos", "w": "Mayo Clinic Arizona, Phoenix (Stati Uniti)", "r": "Autore senior del primo studio retrospettivo trovato in assoluto sulla tua esatta combinazione — tendine quadricipitale con tenodesi laterale (LET) modificata secondo Lemaire — pubblicato su Arthroscopy l'1 luglio 2026 e riemerso solo oggi durante la ricontrollo delle ritrattazioni; corrispondenza tecnica diretta, non di fama; sostituisce la proposta invariata di Adam B. Yanke (5 settembre)."}];
var BRIEF_TEXT="Domenica: la settimana in breve, prima del giorno di oggi. Quattro lavori hanno segnato gli ultimi sette giorni. Il 31 agosto il consensus internazionale HSS sull'artrofibrosi dopo protesi totale ha spostato l'enfasi dalla gestione tardiva alla prevenzione precoce. Il 2 settembre una revisione sistematica su 4.153 adolescenti (J ISAKOS) ha dato il primo segnale diretto sul tuo innesto — tendine quadricipitale più LET — anche nel paziente scheletricamente immaturo. Il 4 settembre il registro svedese collegato alla federazione calcio, 10.693 calciatori, non ha trovato alcuna associazione fra tipo di innesto e revisione, ma un rischio più alto di LCA controlaterale nelle donne con tendine quadricipitale. Il 5 settembre tre studi nello stesso giorno hanno mosso la tensione sul rinforzo laterale (LET) da tre angoli diversi, senza chiuderla. La tensione più toccata questa settimana resta T1a — il LET su innesto rigido — che si allontana sempre di più da una lacuna teorica e si avvicina a un terreno di evidenza reale, ancora incompleto sul tuo costrutto esatto.\n\nOggi, domenica, cinque lavori, un arancione e nessun rosso. Il PICK: una revisione che passa in rassegna sei sistemi robotici commerciali, VELYS compreso, e conclude che nessuno soddisfa i criteri tecnici di una vera intelligenza artificiale autonoma — restano strumenti di assistenza di precisione, non sistemi che decidono da soli. Una coorte spagnola su 115 calciatori professionisti mostra che il rientro in campo dopo il LCA, 97,7% dei casi, non equivale al recupero della carriera: un giocatore su tre scende di categoria entro un anno, il valore di mercato cala fino al 47,7% a cinque anni. Una coorte cinese isola il segno del «jumping patella» come predittore di esito peggiore dopo ricostruzione isolata dell'MPFL — la tua area chirurgica, anche se con fissazione diversa dalla tua. Una meta-analisi di 8 studi non dimostra un vantaggio significativo del templating con intelligenza artificiale sulla scelta della taglia della protesi di ginocchio. E una coorte di Pittsburgh, seguita fino a 25 anni, mostra che il trapianto di menisco da allograft — tecnica che non esegui — dura a lungo ma non per sempre, con un segnale statisticamente fragile sul sesso femminile come fattore di rischio.\n\nFuori dalla finestra dei 30 giorni ma trovato solo oggi, durante la ricerca di sfondo su quadricipite e LET: il primo studio retrospettivo mai pubblicato esattamente sulla tua combinazione — tendine quadricipitale con tenodesi laterale Lemaire — mostra un fallimento dell'innesto più basso con l'aggiunta del LET, 14,8% contro 29,6% (p=0,02). Non è una scheda di oggi per rispetto della finestra di attualità, ma è aggiunto a T1a nella memoria: dettagli nella sezione tensioni.\n\nIl raccoglitore notturno non è passato anche questa notte — terzo giorno consecutivo con lo stesso disallineamento strutturale: richiami, congressi, società e destino dei verdetti restano non verificati. Le ritrattazioni sono state comunque ricontrollate a mano su tutto il perimetro citato, storico compreso: nessun nuovo esito oltre a quello già noto e pubblicato come scheda il 3 settembre.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Buongiorno. Oggi è domenica, quindi iniziamo con la settimana: quattro lavori l'hanno segnata, e la tensione più toccata resta il rinforzo laterale sull'innesto rigido."}, {"chi": "B", "t": "Quella che segui su ogni paziente operato di crociato. A che punto siamo?"}, {"chi": "A", "t": "Il 2 settembre una revisione su oltre quattromila adolescenti ha dato il primo segnale diretto sulla tua combinazione, quadricipite più LET, anche nei più giovani. Il 4 settembre un registro svedese su quasi undicimila calciatori non ha trovato differenze per tipo di innesto sulla revisione, ma un rischio più alto di crociato controlaterale nelle donne con tendine quadricipitale."}, {"chi": "B", "t": "E il 5 settembre?"}, {"chi": "A", "t": "Tre studi nello stesso giorno, in direzioni diverse: nessuno chiude la questione, ma insieme la rendono più concreta."}, {"chi": "B", "t": "Passiamo a oggi. Cinque lavori, dici?"}, {"chi": "A", "t": "Cinque, un arancione, nessun rosso. Il PICK è una revisione su sei sistemi robotici commerciali, VELYS compreso: nessuno è davvero intelligenza artificiale autonoma, restano strumenti di assistenza molto precisi."}, {"chi": "B", "t": "Quindi il VELYS non decide da solo."}, {"chi": "A", "t": "Esatto, e non è un difetto: la decisione resta tua, ed è così che deve essere."}, {"chi": "B", "t": "Cos'altro c'è oggi?"}, {"chi": "A", "t": "Una coorte spagnola su calciatori professionisti: il 97,7% torna in campo dopo il crociato, ma un giocatore su tre scende di categoria entro un anno, e il valore di mercato cala parecchio nel tempo. Poi una coorte cinese: un segno particolare della rotula durante il movimento, il jumping, predice risultati peggiori dopo la sola ricostruzione dell'MPFL."}, {"chi": "B", "t": "E sulla protesi?"}, {"chi": "A", "t": "Una meta-analisi di otto studi non trova un vantaggio dimostrato del templating con intelligenza artificiale sulla scelta della taglia — funziona un po' meglio solo insieme alla TC tridimensionale. E una coorte di Pittsburgh sul trapianto di menisco da allograft, seguita fino a venticinque anni: dura a lungo ma non per sempre, con un segnale fragile che le donne rischino un po' di più. Non è una tua tecnica, ma resta utile saperlo."}, {"chi": "B", "t": "C'è dell'altro fuori dai cinque lavori di oggi?"}, {"chi": "A", "t": "Sì, trovato oggi cercando sullo sfondo intorno al quadricipite e al LET: il primo studio mai uscito esattamente sulla tua combinazione mostra meno fallimenti dell'innesto con l'aggiunta della tenodesi. È vecchio di qualche mese, quindi non è una scheda di oggi, ma lo trovi nelle tensioni."}, {"chi": "B", "t": "E il raccoglitore notturno?"}, {"chi": "A", "t": "Fermo per il terzo giorno di fila, stesso disallineamento di orario: richiami, congressi e società restano non verificati. Le ritrattazioni le ho ricontrollate comunque a mano, tutte: nessuna novità oltre a quella già nota."}];
